(function(root){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const palettes={nature:{bg:'#f5f1e7',ink:'#234b3e',muted:'#6d796c',line:'#d3d8c9',accent:'#be7548',card:'#fffdf7'},ink:{bg:'#252b29',ink:'#f4eee0',muted:'#abae9f',line:'#51554b',accent:'#e4a255',card:'#303831'},clean:{bg:'#fffefa',ink:'#282e35',muted:'#7d7d78',line:'#e2ded3',accent:'#b44237',card:'#f5f3ed'}};
function food(kind=0){const seed=kind%4;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 180"><rect width="240" height="180" fill="${['#e6e0cf','#e3d7c8','#dce2cd','#e2e4da'][seed]}"/><ellipse cx="125" cy="144" rx="82" ry="13" fill="#414b3120"/><ellipse cx="120" cy="94" rx="94" ry="69" fill="#b9b8a2"/><ellipse cx="120" cy="89" rx="91" ry="66" fill="#fcf9ea"/><ellipse cx="120" cy="89" rx="76" ry="53" fill="#e8e2ce"/>${seed===0?`<path d="M65 84 Q77 45 119 54 L169 86 Q175 110 145 125 L92 124 Q55 112 65 84" fill="#ad6439"/><path d="M76 79 Q97 48 130 67 L159 89 Q162 110 130 115 L91 108Z" fill="#d79250"/>${[0,1,2,3].map(i=>`<path d="M${85+i*18} ${72+i*5} l-9 31" stroke="#7c4930" stroke-width="4"/>`).join('')}<path d="M76 61q-20-20-32 4q5 17 28 13M159 68q-2-25 24-21q9 18-15 29" fill="#557945"/><circle cx="168" cy="115" r="13" fill="#d86742"/>`:seed===1?`<path d="M66 78 L119 48 L176 91 L132 126Z" fill="#d88b68"/><path d="M70 81 L120 54 L170 92 L130 119Z" fill="#eeac87"/>${[0,1,2,3,4].map(i=>`<path d="M${83+i*15} ${72-i*2} l-1 29" stroke="#f7cfad" stroke-width="3"/>`).join('')}<circle cx="67" cy="115" r="18" fill="#dac779"/><circle cx="67" cy="115" r="13" fill="#f4df9d"/><path d="M157 59q23-21 29 3q-6 22-28 13" fill="#557448"/>`:seed===2?`${[0,1,2,3,4,5,6].map((v)=>`<ellipse cx="${76+(v%3)*36}" cy="${65+Math.floor(v/3)*25}" rx="24" ry="16" transform="rotate(${v*23} ${76+(v%3)*36} ${65+Math.floor(v/3)*25})" fill="${['#6e8a47','#9baa68','#4f713f'][v%3]}"/>`).join('')}<circle cx="93" cy="78" r="13" fill="#d8854a"/><circle cx="142" cy="107" r="13" fill="#cd7350"/><path d="M89 103l31-29 21 16-36 24Z" fill="#eee1b1"/>`:`<ellipse cx="121" cy="104" rx="49" ry="29" fill="#467149"/><path d="M81 100 L87 57 Q119 42 155 57 L164 100 Q126 126 81 100" fill="#8eae70"/><ellipse cx="121" cy="57" rx="34" ry="17" fill="#b6c88f"/><path d="M105 54q12-26 28-1" fill="#f2eada"/><ellipse cx="133" cy="56" rx="10" ry="4" fill="#567e47"/>`}<g fill="#f6edce">${[0,1,2,3,4,5].map(i=>`<ellipse cx="${83+i*15}" cy="${82+(i%3)*12}" rx="2" ry="1" transform="rotate(30)"/>`).join('')}</g></svg>`}
function artURI(kind){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(food(kind))}
function dimensions(s){return {w:1000,h:1000*Number(s.height)/Number(s.width)}}
function positions(s,page){const {w,h}=dimensions(s),portrait=h>w,cols=portrait?2:(Number(s.density)===6?3:2),rows=Math.ceil(page.items.length/cols),top=portrait?260:150,bottom=portrait?120:65,gap=20,cw=(w-100-(cols-1)*gap)/cols,ch=(h-top-bottom-(rows-1)*gap)/rows;return page.items.map((item,i)=>{let idx=i;if(s.variant%2&&page.items.length>1)idx=page.items.length-1-i;const o=s.overrides[item.id]||{};return {item,x:o.x??50+(idx%cols)*(cw+gap),y:o.y??top+Math.floor(idx/cols)*(ch+gap),cw,ch,scale:o.scale||1,locked:!!o.locked}})}
function svg(s,page,selected=null){const p=palettes[s.style],{w,h}=dimensions(s),portrait=h>w;page=page||{id:'p0',items:[]};const text=(x,y,size,str,color=p.ink,more='')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" ${more}>${esc(str)}</text>`;
let out=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 ${w} ${h}" role="img" aria-label="菜单成品预览" font-family="Microsoft YaHei, sans-serif"><rect width="${w}" height="${h}" fill="${p.bg}"/><path d="M32 32H968V${h-32}H32Z" fill="none" stroke="${p.line}"/>`;
out+=text(52,68,12,'SEASONAL TABLE / AUTUMN EDITION',p.accent,'letter-spacing="3"');out+=text(50,portrait?132:111,portrait?48:36,s.brand,p.ink,'font-family="SimSun, serif" font-weight="bold"');out+=text(52,portrait?170:133,12,s.subtitle,p.muted);
if(s.logo)out+=`<image href="${esc(s.logo)}" x="885" y="48" width="62" height="62" preserveAspectRatio="xMidYMid meet"/>`;else out+=`<rect x="894" y="56" width="49" height="49" rx="2" fill="none" stroke="${p.accent}"/>`+text(907,89,23,'山',p.accent,'font-family="SimSun,serif"');
if(portrait)out+=text(50,224,13,s.goal+' / '+(s.language==='双语'?'SEASONAL FAVORITES':'当季推荐'),p.accent,'letter-spacing="2"');
for(const pos of positions(s,page)){const {item,x,y,cw,ch,scale,locked}=pos,o=s.overrides[item.id]||{},has=item.image||item.art,vertical=portrait;const clip='clip-'+page.id+'-'+item.id;out+=`<g data-component="${item.id}" transform="translate(${x} ${y}) scale(${scale})"><rect width="${cw}" height="${ch}" rx="3" fill="${p.card}"/>`;
const iw=vertical?cw-28:Math.min(cw*.4,ch-22),ih=vertical?Math.min(ch*.53,230):ch-22,ix=vertical?14:12,iy=vertical?14:11;
if(has){out+=`<defs><clipPath id="${clip}"><rect x="${ix}" y="${iy}" width="${iw}" height="${ih}" rx="3"/></clipPath></defs><image href="${esc(item.image||artURI(item.kind))}" x="${ix}" y="${iy}" width="${iw}" height="${ih}" preserveAspectRatio="xMidYMid ${o.crop==='contain'?'meet':'slice'}" clip-path="url(#${clip})"/>`;}
const tx=vertical?18:(has?iw+25:20),ty=vertical?(has?ih+40:45):37,sz=Number(s.density)===6?20:22;
out+=text(tx,ty-14,9,item.category,p.accent);out+=text(tx,ty+10,sz,item.name,p.ink,'font-weight="bold"');if(s.language==='双语')out+=text(tx,ty+31,10,item.en,p.muted);out+=text(tx,Math.min(ch-17,ty+65),25,item.price===null?'待确认':'¥ '+Number(item.price).toFixed(2).replace(/\.00$/,''),p.accent,'font-family="Georgia,serif"');if(s.featured===item.id)out+=text(cw-58,20,9,'招牌推荐',p.accent);
if(selected===item.id)out+=`<rect x="-2" y="-2" width="${cw+4}" height="${ch+4}" fill="none" stroke="#376cf0" stroke-width="3" stroke-dasharray="6 4"/>`;if(selected&&locked)out+=`<rect x="${cw-17}" y="${ch-17}" width="13" height="13" rx="2" fill="#376cf0"/>`;out+='</g>';}
out+=`<path d="M50 ${h-51}H950" stroke="${p.line}"/>`+text(50,h-30,10,s.promo||'用心料理 · 随季而食',p.muted)+text(860,h-30,10,'MENU / '+(MenuModel.pages(s).findIndex(x=>x.id===page.id)+1).toString().padStart(2,'0'),p.muted);return out+'</svg>';
}
root.MenuRenderer={svg,food,artURI,dimensions,positions,esc,palettes};
})(window);
